pub(crate) fn find_generated_request(
    request_name: &str,
) -> Option<(
    &'static GeneratedInterfaceSpec,
    &'static GeneratedMessageSpec,
)> {
    let (interface_name, request_leaf) = request_name.split_once('.')?;
    for protocol in GENERATED_PROTOCOLS {
        for interface in protocol.interfaces {
            if interface.name != interface_name {
                continue;
            }
            if let Some(request) = interface
                .requests
                .iter()
                .find(|request| request.name == request_leaf)
            {
                return Some((interface, request));
            }
        }
    }
    None
}

